    payload = {
        "birth_date": "1974-02-24",
        "birth_time": "05:30:00",
        "birth_location": "seoul",
        "gender": "M",
    }
    resp = client.put(
        "/api/v1/auth/me/profile",
        headers=_auth_header(data["access_token"]),
        json=payload,
    )
    assert resp.status_code == 200, resp.text
    body = resp.json()
    assert body["birth_date"] == "1974-02-24"
    assert body["birth_time"] == "05:30:00"
    assert body["birth_location"] == "seoul"
    assert body["user_id"] == data["user"]["id"]


